select * from customer limit 22
--Total revenue generated by male vs female
select gender,SUM(purchase_amount) as revenue
from customer
group by gender

--which cuyomers used a discount and still spent more thn the average purchase 
select customer_id,purchase_amount
from customer
where discount_applied ='Yes' and purchase_amount>=(select avg(purchase_amount)from customer) 

--which are the top 5 products with the highest average review rating
select item_purchased,round(avg(review_rating::numeric),2) as "Average Product Rating"
from customer
group by item_purchased
order by avg(review_rating) desc
limit 5;

--compare the average purchase amount between standard and express shipping
select avg(purchase_amount),shipping_type
from customer
where shipping_type IN ('Standard','Express') 
group by shipping_type

--DO subscribed customers spend more ? compared

with customer_type as(
select customer_id, previous_purchases,
case when previous_purchases = 1 then 'New'
when previous_purchases between 2 and 11 then 'Returning'
else  'Loyal'
end as customer_segment
from customer
)
select customer_segment, count(*) as "Number of Customer"
from customer_type
group by customer_segment



select category,
item_purchased,
count(customer_id) as total_orders,
ROW_NUMBER() OVER(PARTITION by category order by count(customer_id)desc) as item_rank from customer
group by category,item_purchased


with item_counts as (
select category,
item_purchased,
count(customer_id) as total_orders,
ROW_NUMBER() OVER(PARTITION by category order by count(customer_id)desc) as item_rank from customer
group by category,item_purchased
)

select item_rank , category,item_purchased, total_orders
from item_counts
where item_rank <=3

select subscription_status,
count(customer_id) as repeatbuyers
from customer
where previous_purchases > 5
group by subscription_status

--total revenue in each age group
select age_group,sum(purchase_amount) as total_revenue
from customer
group by age_group
order by total_revenue desc 
